referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const choice = { ...d.defaults, ...d.props };
  const out = [d.base];
  for (const k of Object.keys(d.variants)) {
    const v = choice[k];
    if (v !== null && Object.hasOwn(d.variants[k], String(v))) out.push(d.variants[k][String(v)]);
  }
  for (const c of d.compounds)
    if (Object.keys(c.when).every((k) => choice[k] === c.when[k])) out.push(c.classes);
  return out.filter(Boolean).join(" ");
}

